/**
 * src/worker/cache/fixture-cache.ts
 *
 * Precomputed analysis for the bundled fixtures, used only after an AI failure
 * (quota, rate limit or timeout; requirement 12.7). Files are generated by
 * scripts/generate-fixture-cache.ts with real Workers AI and committed as
 * src/worker/cache/precomputed/<sha256>-<bcp47>.json.
 */

import { AnalyzeResponseSchema } from '../../shared/schemas.js';
import type { AnalyzeResponse } from '../../shared/types.js';

/** Bundled at build time. Empty until the cache has been generated (task 37.1). */
const BUNDLED = import.meta.glob<unknown>('./precomputed/*.json', { eager: true, import: 'default' });

export type FixtureCacheStore = Readonly<Record<string, unknown>>;

/** Store keyed by "<hash>-<tag>" from the bundled files. */
export function bundledStore(files: Record<string, unknown> = BUNDLED): FixtureCacheStore {
  const store: Record<string, unknown> = {};
  for (const [path, value] of Object.entries(files)) {
    const name = path.split('/').pop()?.replace(/\.json$/, '');
    if (name) store[name] = value;
  }
  return store;
}

const DEFAULT_STORE = bundledStore();

export function cacheKey(contentHash: string, interfaceLanguage: string): string {
  return `${contentHash}-${interfaceLanguage}`;
}

/**
 * Cached analysis for (hash, language), marked `servedFromCache: true`, or null
 * when there is none or the stored file does not pass the schema.
 */
export function lookupFixtureCache(
  contentHash: string,
  interfaceLanguage: string,
  store: FixtureCacheStore = DEFAULT_STORE,
): AnalyzeResponse | null {
  if (!/^[0-9a-f]{64}$/.test(contentHash)) return null;
  const entry = store[cacheKey(contentHash, interfaceLanguage)];
  if (entry === undefined) return null;
  const parsed = AnalyzeResponseSchema.safeParse(entry);
  return parsed.success ? { ...parsed.data, servedFromCache: true } : null;
}
